Method.Implementation:

	do ##super()
	$$$TRACE("$$$$$ Inside OnInit() method...")	
	#dim status as %Status
	set status = $$$OK	
	$$$TRACE("IHC.ITF.ITFCOMMON.Util.xmlToJsonConvertor OnInit.. Load JarFile "_ ..JarFiles)
	Set p=1

		For {
			Set piece=$P(..JarFiles,":",p)
			Quit:piece=""
			set p = p+1
			try {
				Set status= ..JavaGateway.%Import(piece)
				$$$TRACE("Jar file: " _ piece _ ", status: " _ status)				
			} catch  exp
    		{
	     		$$$LOGERROR("Exception in jar file import: " _ exp)
    		}
		}
	$$$TRACE("BaseOperation OnInit status: " _ status)
    return status

  #DIM status AS %Status
  set status = $$$OK
  try{
   set xStr = pRequest.StringValue
   Set tSC = ..GetConnection(.tJavaGateway)
   If $$$ISOK(tSC){
     $$$TRACE("Here to call XML to JSON process..."_xStr)
     set x2j = ##class(org.ihc.itf.util.convertXmlToJson).%New(tJavaGateway)
	 set pResponse=##class(Ens.StringResponse).%New()
	 set pResponse.StringValue=""
	 set jStr = x2j.xml2Json(xStr)
	 $$$TRACE("returned json str: " _ jStr)
	 If jStr="" {
	   $$$TRACE(">>>>>jStr is not an object")
       Set sc = $System.Status.Error($$$GeneralError,"xmlToJsonConvertor returned null.")
       Quit
     }
     set pResponse.StringValue=jStr
   }	
  }catch err{
	$$$TRACE("Exception Calling xmlToJsonConvertor: " _ err)
	set status = $$$ERROR("Exception in XmlToJson Operation")
  }

  return status
